import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const a="/assets/assistent-datenpunkt.BFI7cQOr.png",m=JSON.parse('{"title":"Mein erster Zähler in 10 Minuten","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/01.erste-schritte/02.erster-zaehler.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md","filePath":"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md","lastUpdated":null}'),s={name:"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md"};function d(u,e,o,l,h,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mein-erster-zahler-in-10-minuten" tabindex="-1">Mein erster Zähler in 10 Minuten <a class="header-anchor" href="#mein-erster-zahler-in-10-minuten" aria-label="Permalink to &quot;Mein erster Zähler in 10 Minuten&quot;">​</a></h1><p><a id="start-values-unit"></a></p><h2 id="was-trage-ich-bei-den-startwerten-ein-und-in-welcher-einheit" tabindex="-1">Was trage ich bei den Startwerten ein (und in welcher Einheit)? <a class="header-anchor" href="#was-trage-ich-bei-den-startwerten-ein-und-in-welcher-einheit" aria-label="Permalink to &quot;Was trage ich bei den Startwerten ein (und in welcher Einheit)?&quot;">​</a></h2><p><strong>Kurz:</strong> Für einen neuen Zähler musst du meist nichts eintragen. Lässt du die Felder leer, setzt SourceAnalytix sie bei der ersten Aktivierung auf den aktuellen Zählerstand und schreibt sie danach bei jedem Periodenwechsel selbst. Trägst du doch etwas ein, ist jeder Startwert ein Zählerstand, kein Verbrauch: der Gesamtstand zu Beginn der Periode in der Zieleinheit, also in der Einheit der Preisdefinition.</p><h3 id="was-ein-startwert-ist" tabindex="-1">Was ein Startwert ist <a class="header-anchor" href="#was-ein-startwert-ist" aria-label="Permalink to &quot;Was ein Startwert ist&quot;">​</a></h3><p>Die Begriffe Gesamtstand, Zieleinheit und Startwert sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a> erklärt. Für die Startwerte heißt das: Der Verbrauch einer Periode ist der Gesamtstand minus der Startwert dieser Periode. Darum gehört in jedes Feld der Stand, den der Zähler zu Beginn der Periode hatte.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Gesamtstand zu diesem Zeitpunkt</th></tr></thead><tbody><tr><td>„Tag&quot;</td><td>heute um 0:00 Uhr</td></tr><tr><td>„Woche&quot;</td><td>am Montag dieser Woche um 0:00 Uhr</td></tr><tr><td>„Monat&quot;</td><td>am 1. dieses Monats um 0:00 Uhr</td></tr><tr><td>„Quartal&quot;</td><td>am 1. Januar, 1. April, 1. Juli oder 1. Oktober um 0:00 Uhr</td></tr><tr><td>„Jahr&quot;</td><td>am 1. Januar um 0:00 Uhr</td></tr></tbody></table><p>Die Uhrzeit ist die Systemzeit des Rechners oder Containers, auf dem ioBroker läuft.</p><h3 id="in-welcher-einheit" tabindex="-1">In welcher Einheit? <a class="header-anchor" href="#in-welcher-einheit" aria-label="Permalink to &quot;In welcher Einheit?&quot;">​</a></h3><p>In der Einheit der Preisdefinition, die du der Quelle zugeordnet hast, nicht in der Einheit deines Datenpunkts. SourceAnalytix rechnet jeden Wert der Quelle zuerst in diese Zieleinheit um und vergleicht ihn erst dann mit den Startwerten. Ab v0.7.0 steht die Zieleinheit im Assistenten und in der Detailansicht der Quelle hinter jedem Feld. Darüber steht im Assistenten „Trage den Zählerstand zu Beginn jeder Periode (0:00 Uhr) ein, in kWh.&quot;, in der Detailansicht „Zählerstand zu Beginn der laufenden Periode in kWh.&quot;. Bis v0.6.x weist im Objekt-Dialog die Überschrift „Startwerte für den jeweiligen Zeitraum, Einheitenskala (z. B. Wh oder kWh) muss mit der Zieleinheit übereinstimmen!&quot; darauf hin.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Beispiel: Dein Zähler liefert 12.345.678 Wh, die Preisdefinition rechnet in kWh. Dann ist der Gesamtstand 12.345,678 kWh, und in das Feld „Tag&quot; gehört zum Beispiel <code>12340</code>, nicht <code>12340000</code>. Ein Startwert in Wh macht den Verbrauch falsch oder negativ.</p></div><h3 id="wann-du-selbst-etwas-eintragst" tabindex="-1">Wann du selbst etwas einträgst <a class="header-anchor" href="#wann-du-selbst-etwas-eintragst" aria-label="Permalink to &quot;Wann du selbst etwas einträgst&quot;">​</a></h3><p>Bei der ersten Aktivierung ersetzt SourceAnalytix jedes Feld, das leer ist oder 0 enthält, durch den aktuellen Gesamtstand. Im Log steht dann „Initialized empty period start values for … from current reading …&quot;. Alle Perioden zählen damit ab dem Moment der Aktivierung. Felder mit einem anderen Wert bleiben, wie du sie eingetragen hast. Den Zähler selbst musst du nicht auf 0 setzen.</p><p>Selbst eintragen lohnt sich nur, wenn der Verbrauch der laufenden Periode vor der Aktivierung mitzählen soll, zum Beispiel der ganze Monat, obwohl du SourceAnalytix erst am 15. einrichtest. Dafür brauchst du die echten Zählerstände von damals, etwa aus deinen Notizen, einem Foto vom Zähler oder der Historie des Datenpunkts.</p><ol><li>Rechne jeden Stand in die Zieleinheit um.</li><li>Wähle im Assistenten „Quelle hinzufügen&quot; im Schritt „Startwerte&quot; die Karte „Verbrauch seit Periodenbeginn mitzählen&quot; (siehe <a href="#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a>).</li><li>Trage die Stände in die Felder „Tag&quot;, „Woche&quot;, „Monat&quot;, „Quartal&quot; und „Jahr&quot; ein. Jedes Feld nennt den Tag, zu dessen Beginn der Stand gilt. Kennst du einen Stand nicht, lass das Feld leer. Diese Periode zählt dann ab der Aktivierung.</li><li>Unter jedem Feld steht „Verbrauch seit Beginn: …&quot;. Passt ein Wert nicht, steht dort der Fehler, und „Weiter&quot; bleibt gesperrt.</li><li>Schließe den Assistenten mit „⚡ Aktivieren&quot; ab.</li><li>Prüfe mit dem nächsten Wert der Quelle die States unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.consumed</code>, zum Beispiel <code>01_currentDay</code> und <code>03_currentMonth</code>. Kein Wert darf negativ sein.</li></ol><p>Bei einer Quelle, die schon läuft, trägst du die Startwerte in ihrer Detailansicht im Abschnitt „Startwerte&quot; ein und übernimmst sie mit „⚡ Übernehmen&quot;. Wie das geht, steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">So korrigierst du die Startwerte</a>.</p><p><strong>Bis v0.6.x:</strong> Startwerte einer laufenden Quelle stehen im Objekt-Dialog des Datenpunkts (Reiter „Objekte&quot;, Schraubenschlüssel) im Bereich „Startwerte für den jeweiligen Zeitraum&quot;.</p><p>Ein Beispiel: Du aktivierst die Quelle am Mittwoch, 15. März. Der Gesamtstand ist gerade 12.480 kWh.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Eintrag</th><th>woher</th></tr></thead><tbody><tr><td>„Tag&quot;</td><td><code>12475</code></td><td>Stand heute um 0:00 Uhr</td></tr><tr><td>„Woche&quot;</td><td><code>12440</code></td><td>Stand am Montag, 13. März</td></tr><tr><td>„Monat&quot;</td><td><code>12300</code></td><td>Stand am 1. März</td></tr><tr><td>„Quartal&quot;</td><td><code>11900</code></td><td>Stand am 1. Januar</td></tr><tr><td>„Jahr&quot;</td><td><code>11900</code></td><td>Stand am 1. Januar</td></tr></tbody></table><p>Dann zeigt SourceAnalytix 5 kWh für heute, 40 kWh für die Woche, 180 kWh für März und 580 kWh für Quartal und Jahr.</p><p>Die Werte müssen zueinander passen: Kein Startwert ist größer als der Gesamtstand, „Tag&quot; ist der größte, und „Monat&quot; ist mindestens so groß wie „Quartal&quot; und dieses mindestens so groß wie „Jahr&quot;. „Woche&quot; ordnest du nach ihrem Beginn ein: Beginnt die Woche noch im Vormonat, ist ihr Startwert kleiner als der des Monats.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ein Startwert über dem Gesamtstand macht den Verbrauch negativ. Ein Startwert, der zu klein ist, macht ihn zu hoch, und eine 0 nach der ersten Aktivierung zeigt den ganzen Zählerstand als Verbrauch, denn sie wird nur beim ersten Mal ersetzt. Wie du solche Werte reparierst, steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Warum sind meine Werte nach der Eingabe von Startwerten negativ?</a> und <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche, zu hohe oder negative Werte korrigieren</a>.</p></div><h3 id="startwerte-gelten-nur-fur-die-laufende-periode" tabindex="-1">Startwerte gelten nur für die laufende Periode <a class="header-anchor" href="#startwerte-gelten-nur-fur-die-laufende-periode" aria-label="Permalink to &quot;Startwerte gelten nur für die laufende Periode&quot;">​</a></h3><p>Bei jedem Periodenwechsel überschreibt SourceAnalytix den Startwert der neuen Periode mit dem dann aktuellen Gesamtstand. Was du einträgst, wirkt also nur bis zum Ende der laufenden Periode. Werte für frühere Tage, Wochen oder Monate kannst du über die Startwerte nicht nachtragen.</p><p>Bei einer Leistungsquelle (W) lässt du die Felder leer. Ihr Gesamtstand beginnt mit der Aktivierung bei 0.</p><p><strong>Bis v0.6.x</strong> gilt das nur für die Einheit <code>W</code>: Bei <code>kW</code>, <code>MW</code> oder <code>mW</code> füllt SourceAnalytix leere Startwerte bei jedem Start mit dem aktuellen Gesamtstand. <strong>Ab v0.7.0</strong> behandelt es alle Leistungseinheiten wie <code>W</code> (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1267" target="_blank" rel="noreferrer">#1267</a>).</p><p><strong>Ab v0.7.0:</strong> Die Startwerte haben keine Voreinstellung 0 mehr. Ein leeres Feld zählt ab jetzt. Komma und Punkt gehen beide als Dezimalzeichen. Ein einzelnes Komma oder ein einzelner Punkt ist immer das Dezimalzeichen: <code>1.283</code> heißt 1,283, nicht 1283. Schreib Zählerstände deshalb ohne Tausenderpunkt (<code>12475,5</code>). Der Assistent und die Detailansicht prüfen die Werte auf dieselbe Weise gegen den aktuellen Gesamtstand und die Reihenfolge von oben. Passt ein Startwert erst geteilt durch 1000, melden sie zum Beispiel „Sieht nach Wh aus – gemeint 1,29 kWh?“. Solange ein Feld einen Fehler zeigt, bleiben „Weiter“ im Assistenten und „⚡ Übernehmen“ in der Detailansicht gesperrt. Unpassende Startwerte schreibt SourceAnalytix beim Start zusätzlich als Warnung ins Log, zum Beispiel <code>Start value day (600) of &lt;Datenpunkt&gt; is larger than the current total 510; the day values will be negative</code> (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1267" target="_blank" rel="noreferrer">#1267</a>).</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/perioden-und-zeit#sourceanalytix-calculate-retroactively-only-activation">Berechnet SourceAnalytix rückwirkend?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#apply-real-meter-reading-cumulativereading">Wie übernehme ich meinen echten Zählerstand?</a></p><p><a id="datapoint-enable-meter-kwh-power"></a></p><h2 id="welchen-datenpunkt-aktiviere-ich-zahler-kwh-oder-leistung-w" tabindex="-1">Welchen Datenpunkt aktiviere ich: Zähler (kWh) oder Leistung (W)? <a class="header-anchor" href="#welchen-datenpunkt-aktiviere-ich-zahler-kwh-oder-leistung-w" aria-label="Permalink to &quot;Welchen Datenpunkt aktiviere ich: Zähler (kWh) oder Leistung (W)?&quot;">​</a></h2><p><strong>Kurz:</strong> Nimm den Gesamtzähler deines Geräts, also den Datenpunkt mit der Energie in kWh oder Wh (bei Gas oder Wasser das Volumen in m³), der nur steigt. Beispiele sind <code>ENERGY_Total</code> bei Tasmota oder <code>GAS_ENERGY</code> statt <code>GAS_POWER</code>. Einen Leistungswert in W nimmst du nur, wenn dein Gerät keinen Zählerstand liefert.</p><h3 id="der-unterschied" tabindex="-1">Der Unterschied <a class="header-anchor" href="#der-unterschied" aria-label="Permalink to &quot;Der Unterschied&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Zählerstand (kWh, Wh, m³ …)</th><th>Leistung (W, kW …)</th></tr></thead><tbody><tr><td>So rechnet SourceAnalytix</td><td>Verbrauch = Gesamtstand − Startwert der Periode</td><td>Jeder Leistungswert wird mit der Zeit bis zum nächsten Wert multipliziert und zum Gesamtstand addiert</td></tr><tr><td>Genauigkeit</td><td>so genau wie der Zähler</td><td>eine Schätzung: wie gut, hängt davon ab, wie oft das Gerät sendet</td></tr><tr><td>SourceAnalytix war gestoppt</td><td>nichts geht verloren, der nächste Wert enthält den Verbrauch der Pause</td><td>die Energie der Pause fehlt, der erste Wert nach dem Start dient nur als neuer Ausgangspunkt</td></tr><tr><td>Gerät startet bei 0</td><td>wird als Reset erkannt, es zählt weiter</td><td>spielt keine Rolle, es gibt keine Reset-Erkennung</td></tr></tbody></table><h3 id="welchen-datenpunkt-du-nicht-nimmst" tabindex="-1">Welchen Datenpunkt du nicht nimmst <a class="header-anchor" href="#welchen-datenpunkt-du-nicht-nimmst" aria-label="Permalink to &quot;Welchen Datenpunkt du nicht nimmst&quot;">​</a></h3><p>Tageswerte wie <code>ENERGY_Today</code> oder „Ertrag heute&quot; gehen jeden Tag auf 0. SourceAnalytix bildet Tag, Woche, Monat, Quartal und Jahr selbst und braucht dafür einen Stand, der weiterläuft. Ein täglich zurückgesetzter Zähler funktioniert zwar, weil SourceAnalytix den Rückgang als Reset erkennt. Was das Gerät zwischen seinem letzten Wert vor Mitternacht und dem ersten danach zählt, fehlt dann aber. Gibt es einen Gesamtzähler, nimm ihn.</p><p>Ab v0.7.0 markiert der Assistent Datenpunkte, deren ID oder Name nach einem Tageswert aussieht (zum Beispiel <code>today</code> oder <code>heute</code>), mit „Tageszähler&quot; und rät, besser den Gesamtzähler zu nehmen.</p><h3 id="wenn-du-nur-einen-leistungswert-hast" tabindex="-1">Wenn du nur einen Leistungswert hast <a class="header-anchor" href="#wenn-du-nur-einen-leistungswert-hast" aria-label="Permalink to &quot;Wenn du nur einen Leistungswert hast&quot;">​</a></h3><ol><li>Starte den Assistenten „Quelle hinzufügen&quot; (siehe <a href="#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a>) und wähle den Leistungs-Datenpunkt.</li><li>Wähle im Schritt „Messart&quot; die Karte „Leistung&quot; und im Schritt „Einheit&quot; <code>W</code> oder <code>kW</code>.</li><li>Wähle im Schritt „Preis&quot; eine Preisdefinition mit einer Energie-Einheit, zum Beispiel kWh. Nur solche sind wählbar. SourceAnalytix rechnet die Leistung in diese Einheit um.</li><li>Setze im Schritt „Berechnung&quot; unter „Für Experten&quot; bei Bedarf „Mittelwert bei Leistung&quot;. Ohne den Haken gilt jeder Wert bis zum nächsten, mit dem Haken der Mittelwert aus beiden. Der Haken passt zu Sensoren, die regelmäßig senden, nicht zu Geräten, die oft abrupt ein- und ausschalten.</li><li>Setze dort „Negative Werte ignorieren&quot;, wenn dein Gerät, zum Beispiel ein Wechselrichter, im ausgeschalteten Zustand eine negative Leistung meldet. Negative Werte zählen dann als 0 W.</li><li>Im Schritt „Startwerte&quot; ist bei einer Leistung nur „Ab jetzt zählen&quot; möglich.</li></ol><p><strong>Bis v0.6.x</strong> heißen die beiden Haken im Objekt-Dialog „Leistungswerte zwischen Aktualisierungen mitteln&quot; und „Negative Leistungswerte ignorieren&quot;.</p><p>Der erste Wert nach der Aktivierung oder nach einem Neustart von SourceAnalytix ist nur der Ausgangspunkt und bringt noch keinen Verbrauch. Geräte, die nur bei einer Änderung senden, werden trotzdem richtig gerechnet, weil der letzte Wert bis zum nächsten gilt.</p><p><strong>Bis v0.6.1:</strong> Bei Quellen in W fehlt an jedem Tageswechsel die Energie zwischen dem letzten Wert vor Mitternacht und dem ersten Wert danach. <strong>Ab v0.6.2</strong> bucht SourceAnalytix diesen Teil dem alten Tag zu und rechnet im neuen Tag ab Mitternacht mit demselben Wert weiter (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a>).</p><p><strong>Ab v0.7.0:</strong> Unter „Maximale Lücke zwischen Leistungswerten (Minuten)“ legst du fest, wie lange ein Leistungswert höchstens gelten darf. Kommt länger kein neuer Wert, zum Beispiel weil das Gerät oder das WLAN ausgefallen ist, zählt dieser Abschnitt als 0, statt mit dem letzten Wert hochgerechnet zu werden. Im Log steht dann <code>No new power value from &lt;Datenpunkt&gt; for &lt;n&gt; min, longer than the maximum gap of &lt;m&gt; min; this interval is not counted</code>. Leer oder 0 heißt aus, so wie bisher. Die Einstellung steht in der Detailansicht der Leistungsquelle unter „Einstellungen“, nicht im Assistenten. Meldet eine Leistungsquelle lange keinen Wert, zeigt der Tab „Probleme&quot; „Leistungsquelle meldet seit langem keinen Wert&quot;. Lass die Einstellung bei Geräten aus, die nur bei einer Änderung senden, oder wähle sie deutlich größer als den längsten normalen Abstand (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1266" target="_blank" rel="noreferrer">#1266</a>).</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a> · <a href="./../referenz/einstellungen#source-types-exist-meter-power">Welche Quelltypen gibt es?</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Zähler, der täglich auf 0 zurückgesetzt wird</a></p><p><a id="configure-sourceanalytix-datapoint"></a></p><h2 id="wo-konfiguriere-ich-sourceanalytix-fur-einen-datenpunkt" tabindex="-1">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt? <a class="header-anchor" href="#wo-konfiguriere-ich-sourceanalytix-fur-einen-datenpunkt" aria-label="Permalink to &quot;Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 in den Instanz-Einstellungen von SourceAnalytix: Im Tab „Übersicht&quot; startet „Quelle hinzufügen&quot; einen Assistenten mit sieben Schritten. Er speichert die Einstellungen am Datenpunkt und aktiviert die Quelle sofort, ohne Neustart. Bis v0.6.x gehst du über den Reiter „Objekte&quot; und das Schraubenschlüssel-Symbol am Datenpunkt (siehe unten).</p><h3 id="bevor-du-anfangst" tabindex="-1">Bevor du anfängst <a class="header-anchor" href="#bevor-du-anfangst" aria-label="Permalink to &quot;Bevor du anfängst&quot;">​</a></h3><ul><li>Die SourceAnalytix-Instanz läuft. Ohne laufende Instanz zeigt der Tab „Übersicht&quot; keine Quellen, und „⚡ Aktivieren&quot; ist gesperrt.</li><li>Im Tab „Preisdefinitionen&quot; gibt es mindestens eine Preisdefinition mit der Einheit, in der gerechnet werden soll, zum Beispiel kWh. Sie wird die Zieleinheit dieser Quelle. Fehlt sie, meldet der Assistent „Es gibt noch keine Preisdefinition.&quot;</li></ul><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen&quot; die Einstellungen von <code>sourceanalytix.0</code> und klicke im Tab „Übersicht&quot; auf „Quelle hinzufügen&quot;.</li><li><strong>„Datenpunkt&quot;:</strong> Suche den Datenpunkt mit dem Zählerstand oder wähle ihn über „Objekt auswählen&quot;. Die Liste „Passende Datenpunkte&quot; zeigt nur Datenpunkte mit einer bekannten Einheit. Welchen du nimmst, steht unter <a href="#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a>.</li><li><strong>„Messart&quot;:</strong> Wähle „Zählerstand&quot; oder „Leistung&quot;. Der Assistent schlägt eine Messart aus der Einheit vor. Bei einem Zählerstand beantwortest du „Springt der Wert manchmal auf 0, z. B. nach einem Stromausfall?&quot;. „Ja&quot; schaltet die Reset-Erkennung ein.</li><li><strong>„Einheit&quot;:</strong> Prüfe die Einheit des Datenpunkts. Darunter steht „Erkannt aus dem Datenpunkt: …&quot;.</li><li><strong>„Preis&quot;:</strong> Wähle die Preisdefinition. Preisdefinitionen mit unpassender Einheit sind mit „andere Einheit&quot; markiert und nicht wählbar. Setze bei Bedarf „Grundpreis dieser Preisdefinition einrechnen&quot;.</li><li><strong>„Berechnung&quot;:</strong> Wähle, was SourceAnalytix berechnen soll: „Verbrauch&quot;, „Kosten&quot; und „Zählerstände speichern&quot;. Alle drei sind vorbelegt.</li><li><strong>„Startwerte&quot;:</strong> Lass „Ab jetzt zählen&quot; gewählt (warum, steht unter <a href="#start-values-unit">Was trage ich bei den Startwerten ein?</a>).</li><li><strong>„Name&quot;:</strong> Gib der Quelle einen Namen. Prüfe die Zusammenfassung und klicke auf „⚡ Aktivieren&quot;.</li></ol><p><img src="'+a+'" alt="Assistent „Quelle hinzufügen“, Schritt „Datenpunkt“ mit passenden Datenpunkten"></p><p>Nach dem Aktivieren wartet der Assistent mit „… ist aktiv. Warte auf den ersten Wert …&quot;. Sobald die Quelle den ersten Wert liefert, steht dort „Erster Wert empfangen: …&quot;, und mit „Zur Quelle&quot; öffnest du ihre Detailansicht. SourceAnalytix legt den Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> an. <code>&lt;Gerät&gt;</code> ist die „Technische ID&quot;, die der Assistent aus dem Namen bildet: Kleinbuchstaben, Ziffern und <code>_</code>, Umlaute werden zu <code>ae</code>, <code>oe</code>, <code>ue</code>. Unter „Für Experten&quot; kannst du sie im letzten Schritt ändern, mit Buchstaben, Ziffern, <code>_</code> und <code>-</code>.</p><p>Die Einstellungen einer Quelle änderst du später in ihrer Detailansicht unter „Einstellungen&quot; und übernimmst sie mit „⚡ Übernehmen&quot;. Auch das wirkt sofort, ohne Neustart. Zahlen kannst du dort mit Komma oder Punkt eingeben.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ohne „Verbrauch&quot; entstehen keine Verbrauchswerte für Tag, Woche, Monat, Quartal und Jahr. Nimmst du „Verbrauch&quot; oder „Kosten&quot; später wieder heraus, löscht SourceAnalytix die zugehörigen States.</p></div><p>Die Detailansicht enthält alle Einstellungen der Quelle, auch die, die der Assistent nicht abfragt: die „Startwerte&quot;, bei Leistungsquellen „Mittelwert bei Leistung&quot; und „Maximale Lücke zwischen Leistungswerten (Minuten)&quot;, bei Quellen in Stück (<code>piece</code>, <code>piece/min</code>) „Impulse pro &lt;Einheit&gt;&quot; und unter „Für Experten&quot; „Jede Aktualisierung addiert ihren Wert&quot; und die „Technische ID&quot;.</p><h3 id="bis-v0-6-x-uber-den-reiter-„objekte" tabindex="-1">Bis v0.6.x: über den Reiter „Objekte&quot; <a class="header-anchor" href="#bis-v0-6-x-uber-den-reiter-„objekte" aria-label="Permalink to &quot;Bis v0.6.x: über den Reiter „Objekte&quot;&quot;">​</a></h3><ol><li>Öffne im Admin den Reiter „Objekte&quot; und suche den Datenpunkt mit dem Zählerstand.</li><li>Klicke in seiner Zeile auf das Schraubenschlüssel-Symbol und klappe den Bereich von <code>sourceanalytix.0</code> auf.</li><li>Setze den Haken bei „aktiviert&quot; und wähle bei „Preisdefinition auswählen&quot; eine Kategorie. Das Feld ist Pflicht, auch wenn du nur den Verbrauch willst. Die Auswahl bleibt leer, wenn die Instanz gestoppt ist.</li><li>Lass „Wählen Sie Einheit&quot; auf „Automatisch erkennen&quot;, wenn der Datenpunkt eine passende Einheit hat.</li><li>Setze unter „Berechnungseinstellungen&quot; die Haken bei „Verbrauch berechnen&quot;, „Kosten berechnen&quot;, bei Bedarf „Inklusive Grundpreis&quot; und „Zählerwerte speichern&quot;. Lass die Startwerte leer und speichere.</li></ol><p>Der Ordner heißt dann wie die „Ausgabe-ID&quot;, die der Dialog aus der ID des Datenpunkts bildet: Punkte werden zu <code>__</code>.</p><p><strong>Ab v0.7.0:</strong> Im Objekt-Dialog bleibt nur der Haken „aktiviert&quot;, ein Hinweis und der Knopf „SourceAnalytix-Einstellungen öffnen&quot;. So siehst du im Reiter „Objekte&quot; weiter, welche Datenpunkte SourceAnalytix nutzt, wie bei History oder InfluxDB. Schaltest du eine Quelle dort ein, setzt SourceAnalytix „Verbrauch&quot;, „Kosten&quot;, „Zählerstände speichern&quot; und die Reset-Erkennung mit Schwelle 1. Eine Preisdefinition fehlt dann noch, deshalb erscheint die Quelle im Tab „Probleme&quot; mit „Keine Preisdefinition gewählt&quot;. Wähle sie in der Detailansicht. Alle übrigen Einstellungen nimmst du nur noch auf der Einstellungsseite vor (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#datapoint-settings-costs-consumption-meter">Was bewirken die Einstellungen am Datenpunkt?</a> · <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber es entstehen keine Ordner</a></p><p><a id="values-consumption-today-yesterday"></a></p><h2 id="wo-finde-ich-meine-werte-tagesverbrauch-heute-gestern" tabindex="-1">Wo finde ich meine Werte (Tagesverbrauch heute/gestern)? <a class="header-anchor" href="#wo-finde-ich-meine-werte-tagesverbrauch-heute-gestern" aria-label="Permalink to &quot;Wo finde ich meine Werte (Tagesverbrauch heute/gestern)?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 siehst du die Werte direkt in den Instanz-Einstellungen: Jede Karte im Tab „Übersicht&quot; zeigt „Heute&quot;, „Monat&quot; und „Jahr&quot;, die Detailansicht der Quelle unter „Werte&quot; auch „Gestern&quot;, „Letzte Woche&quot;, „Vormonat&quot; usw. Als States liegen sie unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear</code>, der heutige Verbrauch zum Beispiel in <code>currentYear.consumed.01_currentDay</code>, der von gestern in <code>currentYear.consumed.01_previousDay</code>.</p><h3 id="die-wichtigsten-states" tabindex="-1">Die wichtigsten States <a class="header-anchor" href="#die-wichtigsten-states" aria-label="Permalink to &quot;Die wichtigsten States&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State unter <code>sourceanalytix.0.&lt;Gerät&gt;</code></th><th>Inhalt</th></tr></thead><tbody><tr><td><code>cumulativeReading</code></td><td>Gesamtstand in der Zieleinheit</td></tr><tr><td><code>currentYear.consumed.01_currentDay</code> bis <code>05_currentYear</code></td><td>Verbrauch heute, diese Woche, diesen Monat, dieses Quartal, dieses Jahr</td></tr><tr><td><code>currentYear.consumed.01_previousDay</code> bis <code>05_previousYear</code></td><td>Verbrauch gestern, letzte Woche, letzten Monat, letztes Quartal, letztes Jahr</td></tr><tr><td><code>currentYear.costs.…</code></td><td>Kosten mit denselben State-Namen</td></tr></tbody></table><p>Beschreibt die Preisdefinition eine Einspeisung („Erlös&quot;), heißen die Ordner <code>delivered</code> und <code>earnings</code> statt <code>consumed</code> und <code>costs</code>. Alle Ordner, die Wochentage, Wochen und Monate und das Archiv je Jahr stehen unter <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a>.</p><h3 id="wann-die-ersten-werte-erscheinen" tabindex="-1">Wann die ersten Werte erscheinen <a class="header-anchor" href="#wann-die-ersten-werte-erscheinen" aria-label="Permalink to &quot;Wann die ersten Werte erscheinen&quot;">​</a></h3><ul><li><strong>Heute, Woche, Monat, Quartal, Jahr:</strong> mit dem ersten Wert, den die Quelle nach der Aktivierung liefert. Bei einer Leistung in W ist der erste Wert nur der Ausgangspunkt, Verbrauch entsteht ab dem zweiten.</li><li><strong>Gestern, letzte Woche usw.:</strong> erst nach dem ersten Periodenwechsel, also frühestens nach der nächsten Mitternacht. Dafür muss in den Instanz-Einstellungen unter „Haupteinstellungen&quot; „Vorheriger Zeitraum&quot; eingeschaltet sein (Standard).</li><li>SourceAnalytix rechnet nur, wenn die Quelle einen neuen Wert sendet. Kommt keiner, bleibt der letzte Wert stehen.</li></ul><p><strong>Bis v0.6.x</strong> gibt es die Übersicht in den Instanz-Einstellungen nicht. Dann siehst du die Werte im Reiter „Objekte&quot; unter <code>sourceanalytix.0</code>.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#consumption-calculated-currentyear-lower-than">Wie wird der Verbrauch berechnet?</a> · <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">Werte werden live oder erst um Mitternacht aktualisiert?</a></p>',70)])])}const b=t(s,[["render",d]]);export{m as __pageData,b as default};
